-- Dog / pet stores, Hyderabad — Google Maps export captured 28 Sep 2026.
-- 120 local businesses loaded as client accounts (is_client = true).
-- Idempotent: re-running inserts nothing new (on conflict do nothing).

-- Storefront columns the desk's client list reads. Additive and idempotent;
-- the BE adds the same set on boot via app/migrations.py.
alter table public.companies add column if not exists phone varchar;
alter table public.companies add column if not exists address text;
alter table public.companies add column if not exists pincode varchar;
alter table public.companies add column if not exists rating double precision;
alter table public.companies add column if not exists reviews_count integer;
alter table public.companies add column if not exists maps_url text;
alter table public.companies add column if not exists latitude double precision;
alter table public.companies add column if not exists longitude double precision;
alter table public.companies add column if not exists source varchar;
alter table public.companies add column if not exists hours json;
alter table public.companies add column if not exists notes text;
alter table public.companies add column if not exists tags json;

create index if not exists ix_companies_source  on public.companies (source);
create index if not exists ix_companies_pincode on public.companies (pincode);
create index if not exists ix_companies_rating  on public.companies (rating);

on conflict (id) do nothing;
